    if (this.reloadTimer > 0) {
      this.reloadTimer -= dt;
      if (this.reloadTimer <= 0) {
        this.finishReload();
      }
    }

    if (this.currentWeapon.hasScope) {
      this.isScoped = isAiming;
    } else {
